Object.entries(DESTINATION_DETAIL_ENRICHMENTS).forEach(([id, extra]) => {
  const destination = DESTINATIONS.find(d => d.id === id);
  if (!destination) return;
  const existingPois = new Set((destination.pois || []).map(p => p.nom));
  (extra.pois || []).forEach(([nom, type]) => { if (!existingPois.has(nom)) destination.pois.push({ nom, type, prix: 'À vérifier', lien: '' }); });
  const existingRestaurants = new Set((destination.restaurants || []).map(r => r.nom));
  (extra.restaurants || []).forEach(([nom, type, prix]) => { if (!existingRestaurants.has(nom)) destination.restaurants.push({ nom, type, prix, note: '★★★★' }); });
});

